      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: expect.stringContaining('Test log message')
    }));
  });

  it('formats entry object correctly', () => {
    logToTerminal({
      message: 'Structured entry message',
      agent: 'Coordinator',
      level: 'stage',
      details: 'Chapter 1'
    });

    expect(fetch).toHaveBeenCalledWith('/api/terminal-log', expect.objectContaining({
      method: 'POST',
      body: expect.stringContaining('"agent":"Coordinator"')
    }));
  });

  it('throttles stream progress logs', () => {
    logStreamProgress('Generating Chapter 1', 100, 'Synthesis', true);
    expect(fetch).toHaveBeenCalledTimes(1);

    // Calling immediately without force should be throttled
    logStreamProgress('Generating Chapter 1', 110, 'Synthesis', false);
    expect(fetch).toHaveBeenCalledTimes(1);

    // Forcing bypasses throttle
    logStreamProgress('Generating Chapter 1', 250, 'Synthesis', true);
    expect(fetch).toHaveBeenCalledTimes(2);
  });

  it('installs console bridge without crashing', () => {
    expect(() => installConsoleBridge()).not.toThrow();
  });
});

import { describe, it, expect } from 'vitest';
import {
  bestsellerAdvisory,
  wornPhrases,
  extractPremiseNames,
  hookScore,
  measureTexture,
  recurrentMotifs,
  rhythmDrift,
  sharedDistinctivePhrasing,
  uniqueNgramRatio,
} from '../utils/novel/analytics';

describe('analytics detectors', () => {
  it('flags a phrase circled across distinct sentences', () => {
    const text = [
      'The upper room held its light through the storm.',
      'He saw the upper room held its light.',
      'By midnight the upper room held its light.',
      'She stared at the cold stairs in silence.',
    ].join(' ');
    const motifs = recurrentMotifs(text);
    expect(motifs.length).toBeGreaterThan(0);
    expect(motifs[0].sentences).toBe(3);
    expect(motifs[0].phrase).toContain('room held its light');
  });

  it('ignores ordinary glue repeated everywhere', () => {
    const text = 'He went to the door and then he went to the window and then he went to the stairs.';
    expect(recurrentMotifs(text)).toEqual([]);
  });

  it('extracts premise names and skips sentence-start common words', () => {
    expect(extractPremiseNames('A love triangle of Aren, Miro and someone else.'))
      .toEqual(['Aren', 'Miro']);
    expect(extractPremiseNames('After the lighthouse goes dark, keeper Aren Miro must relight it.'))
      .toEqual(['Aren Miro']);
    // Position alone never disqualifies: a name first is still a name.
    expect(extractPremiseNames('Aren wept.')).toEqual(['Aren']);
    // A capitalized common noun is still extracted — letting it pass is the
    // gaps filter's job, not the extractor's silence.
    expect(extractPremiseNames('Hope dies last in the garrison.')).toEqual(['Hope']);
  });

  it('holds rhythm on even prose and flags a collapse', () => {
    const even = Array.from({ length: 15 }, () => 'The old lighthouse keeper climbed the narrow winding stairs very slowly.').join(' ');
    expect(rhythmDrift(even).drifted).toBe(false);
    const collapse = [
      ...Array.from({ length: 10 }, () => 'The old lighthouse keeper climbed the narrow winding stairs very slowly each night without fail.'),
      ...['Dark and cold.', 'Gone by dawn.', 'Run and hide.', 'No way back.', 'Hold the line.', 'Now we wait.'],
    ].join(' ');
    const report = rhythmDrift(collapse);
    expect(report.sentences).toBeGreaterThanOrEqual(12);
    expect(report.drifted).toBe(true);
  });

  it('scores a hooked opening above a flat one', () => {
    expect(hookScore('"Run!" she shouted. The alarm tore through the station. Who had opened the gate?')).toBeGreaterThan(
      hookScore('It was a quiet morning in the village. There was bread on the table.'),
    );
  });

  it('rates varied phrasing above copy-paste', () => {
    const varied = 'The sea kept its counsel. Gulls argued over bright scraps. A bell counted the fog.';
    const repeated = 'The sea kept its counsel. The sea kept its counsel. The sea kept its counsel.';
    expect(uniqueNgramRatio(varied)).toBeGreaterThan(uniqueNgramRatio(repeated));
  });

  it('measures dialogue, paragraph length, comparisons and beats', () => {
    const text = [
      '"We leave at dawn," she said.',
      '',
      'He nodded like a man accepting winter.',
      '',
      '"Then we run."',
    ].join('\n');
    const texture = measureTexture(text);
    expect(texture.dialogueShare).toBeGreaterThan(0.2);
    expect(texture.medianParagraphWords).toBeGreaterThan(2);
    expect(texture.similesPer1000).toBeGreaterThan(0);
    expect(texture.taggedSpeechShare).toBeCloseTo(0.5, 1);
  });

  it('finds a staging about to be restaged, and stays quiet otherwise', () => {
    const chapter = 'The upper room held its light through the storm. Aren watched the stairs.';
    const plan = 'Upper room, night. The upper room held its light while they waited.';
    const shared = sharedDistinctivePhrasing(plan, chapter);
    expect(shared.some(phrase => phrase.includes('room held its light'))).toBe(true);
    expect(sharedDistinctivePhrasing('A sunny platform above the roaring waterfall.', chapter)).toEqual([]);
    expect(sharedDistinctivePhrasing('He went to the door.', chapter)).toEqual([]);
  });

  it('advises on a weak hook and a recap ending', () => {
    const findings = bestsellerAdvisory('It was a quiet morning. There was bread. In summary, they had a fine day.');
    expect(findings.map(finding => finding.id)).toContain('weak-opening-hook');
  });
});

describe('wornPhrases', () => {
  // One sentence carrying the tic, repeated with different surroundings, the way
  // a generated book actually wears a somatic beat out.
  const filler = 'The room held its shapes in the grey afternoon and nobody moved through them. ';
  const tic = (n: number) => Array.from({ length: n }, (_, i) => `On the ${i + 1} day his shoulder tightened against the cold air. `).join('');

  it('reports a two-word beat that returns at a rate, with its count', () => {
    const text = tic(7) + filler.repeat(120);
    const found = wornPhrases(text);
    const tightened = found.find(item => item.phrase === 'shoulder tightened');
    expect(tightened?.uses).toBe(7);
    expect(tightened!.per1000).toBeGreaterThan(0.5);
  });

  it('says nothing about a book that repeats its own subject by name', () => {
    // A capitalized invented term is the book's own device, not a tic:
    // capitalized spans are skipped.
    const text = 'The Kindral flared between them. '.repeat(12) + filler.repeat(120);
    expect(wornPhrases(text).some(item => item.phrase.includes('echo'))).toBe(false);
  });

  it('does not report contractions or short books', () => {
    const text = "She didn't know what he didn't say. ".repeat(10) + filler.repeat(120);
    expect(wornPhrases(text).some(item => item.phrase.includes('didn'))).toBe(false);
    expect(wornPhrases(tic(9))).toEqual([]);
  });
});

import { describe, expect, it } from 'vitest';
import { applyForwardToHandoff, buildSceneHandoff, compactHandoff, HANDOFF_LIMITS } from '../utils/novel/v2/handoff';
import { DEFAULT_DIGEST } from '../utils/novel/v2/stateDigest';
import type { ForwardUpdate, SceneHandoff, ScenePlan, StateDelta, StoryState } from '../utils/novel/v2/types';

const scene = (id: string): ScenePlan => ({
  id, pov_id: 'C01', location: 'Lighthouse', story_time: 'night', participants: ['C01'], initial_conditions: [],
  function: 'f', participant_intentions: [], pressure_or_uncertainty: '', development: '',
  required_outcome: 'Aren opens the outer door.', flexible_elements: [], required_fact_refs: [],
  required_source_refs: [], setup_or_payoff: [], transition_to_next: '', target_words: 800, outcome_kind: 'position',
});

function delta(index: number): StateDelta {
  return {
    proper_names: [], name_variants: [],
    events: [0, 1, 2, 3].map(step => ({ description: `Event ${index}.${step} happens.`, participants: ['C01'], evidence_refs: ['p1'] })),
    state_changes: [], knowledge_changes: [], belief_changes: [], intentions_and_commitments: [],
    reader_disclosures: [`Disclosure ${index}.a`, `Disclosure ${index}.b`],
    threads_opened: [], threads_resolved: [], contradictions: [],
    uncertainties: [{ question: `Question ${index}?`, evidence_refs: ['p1'], relevant_to_next_scene: true }],
    plan_deviations: [],
  };
}

/** A book of `scenes` scenes, folded the way the pipeline folds it, handoff carried forward. */
function write(scenes: number): { handoffs: SceneHandoff[]; state: StoryState } {
  const state: StoryState = {
    facts: [{ id: 'F1', statement: 'The door answers to the lamp.', evidence_refs: ['p1'] }],
    events: [], conditions: {}, knowledge: {}, beliefs: {}, reader_disclosures: [], names: [],
  };
  const handoffs: SceneHandoff[] = [];
  for (let index = 1; index <= scenes; index++) {
    const change = delta(index);
    change.events.forEach((event, step) => state.events.push({ id: `S${index}-e${step + 1}`, ...event }));
    state.reader_disclosures.push(...change.reader_disclosures);
    handoffs.push(buildSceneHandoff({
      scene: scene(`CH01_S${String(index).padStart(2, '0')}`), state, delta: change, resolutions: [], threads: [],
      previous: handoffs.at(-1) || null,
    }));
  }
  return { handoffs, state };
}

describe('a handoff the length of a scene, not of the book', () => {
  it('stops growing once the book is longer than the stretch it carries', () => {
    const { handoffs } = write(80);
    const size = (handoff: SceneHandoff) => JSON.stringify(handoff).length;
    // Eighty scenes is a twenty-chapter book. Unbounded, the last handoff was
    // forty times the size of the tenth.
    expect(size(handoffs[79])).toBeLessThan(size(handoffs[19]) * 1.1);
    const last = handoffs[79];
    expect(last.forbidden_restatements).toHaveLength(HANDOFF_LIMITS.restatements);
    expect(last.open_questions).toHaveLength(HANDOFF_LIMITS.questions);
    expect(last.known_to_reader).toHaveLength(1 + DEFAULT_DIGEST.events + DEFAULT_DIGEST.disclosures);
  });

  it('keeps every fact, the newest of everything else, and says what it left out', () => {
    const last = write(80).handoffs[79];
    expect(last.known_to_reader).toContain('The door answers to the lamp.');
    expect(last.known_to_reader).toContain('Event 80.3 happens.');
    expect(last.known_to_reader).not.toContain('Event 1.0 happens.');
    expect(last.forbidden_restatements).toContain('Disclosure 80.b');
    expect(last.open_questions.at(-1)).toBe('Question 80?');
    expect(last.history_note).toMatch(/the 24 most recent of 320 recorded events/);
    expect(last.history_note).toMatch(/Everything earlier happened, still holds/);
  });

  it('adds no note to a book short enough to carry whole', () => {
    const first = write(2).handoffs[1];
    expect(first.history_note).toBeUndefined();
    expect(first.known_to_reader).toContain('Event 1.0 happens.');
  });

  it('brings a handoff stored before the limits inside them, and leaves a current one alone', () => {
    const many = (label: string, count: number) => Array.from({ length: count }, (_, index) => `${label} ${index + 1}`);
    const legacy: SceneHandoff = {
      after_scene_id: 'CH04_S04', known_to_reader: many('Known', 240), confirmed_changes: [], current_conditions: {},
      open_questions: many('Question', 55), active_intentions: [], previous_outcome: 'o', required_new_outcome: '',
      forbidden_restatements: many('Told', 237),
    };
    const compact = compactHandoff(legacy);
    expect(compact.forbidden_restatements).toHaveLength(HANDOFF_LIMITS.restatements);
    expect(compact.forbidden_restatements.at(-1)).toBe('Told 237');
    expect(compact.known_to_reader).toHaveLength(DEFAULT_DIGEST.events + DEFAULT_DIGEST.disclosures);
    expect(compact.open_questions.at(-1)).toBe('Question 55');
    expect(compact.history_note).toMatch(/most recent of 240 things the reader knows/);
    const current = write(80).handoffs[79];
    expect(compactHandoff(current)).toBe(current);
  });

  it('stays inside the limits after the chapter reconciliation adds to it', () => {
    const last = write(80).handoffs[79];
    const forward = {
      chapter_outcome: 'The chapter ends with the door open.', consequences_to_carry_forward: [],
      next_chapter_inputs: { starting_situation: '', active_intentions: [], necessary_content: [], relevant_fact_refs: [], source_refs_to_retrieve: [] },
      plan_updates: [], ending_readiness: { established_requirements: [], remaining_requirements: [], capacity_problems: [] },
      unresolved_blockers: ['Who cut the fuel line?'],
    } as ForwardUpdate;
    const enriched = applyForwardToHandoff(last, forward);
    expect(enriched.forbidden_restatements).toHaveLength(HANDOFF_LIMITS.restatements);
    expect(enriched.forbidden_restatements.at(-1)).toBe('The chapter ends with the door open.');
    expect(enriched.open_questions.at(-1)).toBe('Who cut the fuel line?');
    expect(enriched.open_questions).toHaveLength(HANDOFF_LIMITS.questions);
  });
});

import { describe, it, expect, vi } from 'vitest';
import { naturalizeClaim, softmax } from '../utils/novel/nli';
import { currentGateMode, setGateModeOverride, runPrewriteGate, type GateScorers } from '../utils/novel/v2/semanticGate';
import { emptyState } from '../utils/novel/v2/store';
import type { ChapterPlan, ScenePlan } from '../utils/novel/v2/types';

// No model weights in tests, ever: the gate takes its scorers injected.
const stubScorers = (rerankScores: number[], nliContradiction: number): GateScorers & { rerank: ReturnType<typeof vi.fn>; scoreNLI: ReturnType<typeof vi.fn> } => ({
  rerank: vi.fn(async () => rerankScores),
  scoreNLI: vi.fn(async () => ({ contradiction: nliContradiction, entailment: 0, neutral: 1 - nliContradiction })),
});

const scene = (overrides: Partial<ScenePlan> = {}): ScenePlan => ({
  id: 'CH02_S01',
  pov_id: 'C01',
  location: 'Upper room',
  story_time: 'Night',
  participants: ['C01'],
  initial_conditions: ['Aren tends the lamp.'],
  function: 'An uneasy night together.',
  participant_intentions: [{ character_id: 'C01', intention: 'Stay awake until dawn.', reason_now: 'The storm.' }],
  pressure_or_uncertainty: 'Whether the light holds.',
  development: 'The upper room held its light while they waited.',
  required_outcome: 'They wait by the lamp.',
  flexible_elements: [],
  required_fact_refs: [],
  required_source_refs: [],
  setup_or_payoff: [],
  transition_to_next: '',
  target_words: 300,
  outcome_kind: 'position',
  ...overrides,
});

const plan = (scenes: ScenePlan[]): ChapterPlan => ({
  status: 'ready',
  chapter: 2,
  function: '',
  starting_situation: '',
  ending_change: '',
  mechanism: 'tend the lamp',
  cost: 'a night of sleep',
  pressure_rung: 2,
  scenes,
  forward_dependencies: [],
  replan_reason: null,
});

const prior = [{ ref: 'Chapter 1', text: 'The upper room held its light over the stairs through the storm. Aren watched the long night.' }];

describe('semantic pre-write gate', () => {
  it('flags a paraphrase-level retelling with its evidence', async () => {
    const scorers = stubScorers([4.9], 0.1);
    const result = await runPrewriteGate(plan([scene()]), prior, emptyState(), scorers, 'full');
    const problems = result.problems.get('CH02_S01') || [];
    expect(problems.some(p => p.code === 'restaging-suspect' && p.detail.includes('Chapter 1'))).toBe(true);
    expect(result.warnings).toEqual([]);
  });

  it('stays quiet below the fitted threshold', async () => {
    const scorers = stubScorers([4.49], 0.1);
    const result = await runPrewriteGate(plan([scene()]), prior, emptyState(), scorers, 'full');
    expect(result.problems.get('CH02_S01') || []).toEqual([]);
  });

  it('flags a plan-vs-memory clash with both sides quoted', async () => {
    const scorers = stubScorers([0.5], 0.92);
    const state = { ...emptyState(), conditions: { 'C01.location': 'Harbor' } };
    const scenes = [scene({ required_outcome: 'Aren stays at the lighthouse by the harbor.' })];
    const result = await runPrewriteGate(plan(scenes), prior, state, scorers, 'full');
    const problems = result.problems.get('CH02_S01') || [];
    expect(problems.some(p => p.code === 'clash-suspect')).toBe(true);
  });

  it('never calls a model when disabled', async () => {
    const scorers = stubScorers([9.9], 0.99);
    const result = await runPrewriteGate(plan([scene()]), prior, emptyState(), scorers, 'off');
    expect(scorers.rerank).not.toHaveBeenCalled();
    expect(scorers.scoreNLI).not.toHaveBeenCalled();
    expect(result.problems.size).toBe(0);
  });

  it('has no mode that claims coverage it does not have', async () => {
    // A light mode ran a small embedder, reported "paraphrase restaging" in the
    // run log, and let a scene be retold nearly beat for beat from one chapter
    // to the next. Either the cross-encoder reads the pair, or nothing claims to.
    const scorers: GateScorers = {
      rerank: vi.fn(async () => [9]),
      scoreNLI: vi.fn(async () => ({ contradiction: 0, entailment: 0, neutral: 1 })),
    };
    const result = await runPrewriteGate(plan([scene()]), prior, emptyState(), scorers, 'full');
    expect(result.mode).toBe('full');
    expect(scorers.rerank).toHaveBeenCalled();
    const off = await runPrewriteGate(plan([scene()]), prior, emptyState(), scorers, 'off');
    expect(off.mode).toBe('off');
    expect(off.problems.size).toBe(0);
  });

  it('ignores any stored setting: a browser always gets the whole check', () => {
    // There is no switch any more. A value left over from when there was one —
    // 'light', 'off', anything — must not quietly hold a reader at less than
    // the full check for every book they write afterwards.
    for (const stored of ['light', 'off', 'on', null]) {
      vi.stubGlobal('localStorage', { getItem: () => stored, setItem: () => {}, removeItem: () => {} } as unknown as Storage);
      try {
        expect(currentGateMode(), `stored ${stored}`).toBe('full');
      } finally {
        vi.unstubAllGlobals();
      }
    }
  });

  it('stays off only where there is nobody to consent to the download', () => {
    // Not a setting — a runtime fact. A test suite that reached for 780MB of
    // weights would not be a test suite, and a script says otherwise for itself.
    expect(currentGateMode()).toBe('off');
  });

  it('lets a runner without storage say what it wants', () => {
    expect(currentGateMode()).toBe('off');
    setGateModeOverride('full');
    try {
      expect(currentGateMode()).toBe('full');
    } finally {
      setGateModeOverride(null);
    }
    expect(currentGateMode()).toBe('off');
  });

  it('degrades to warnings when a scorer dies, never failing the run', async () => {
    const scorers: GateScorers = {
      rerank: async () => { throw new Error('worker gone'); },
      scoreNLI: async () => ({ contradiction: 0, entailment: 0, neutral: 1 }),
    };
    const result = await runPrewriteGate(plan([scene()]), prior, emptyState(), scorers, 'full');
    expect(result.problems.size).toBe(0);
    expect(result.warnings.join(' ')).toMatch(/unavailable/);
  });
});

describe('nli pure helpers', () => {
  it('naturalizes telegraphic claims into propositions', () => {
    expect(naturalizeClaim('Aren location: Harbor')).toBe('Aren is at Harbor.');
    expect(naturalizeClaim('Already a sentence.')).toBe('Already a sentence.');
  });

  it('softmax normalizes to a distribution', () => {
    const out = softmax([2, 1, 0]);
    expect(out.reduce((a, b) => a + b, 0)).toBeCloseTo(1, 5);
    expect(out[0]).toBeGreaterThan(out[2]);
    expect(softmax([])).toEqual([]);
  });
});
